SELECT DIV_RVC_RATE        AS rvcRate
      ,DIV_DE_MINIMIS_RATE AS deMinimisRate
FROM   DIVISION
WHERE  COMPANY_CODE = #{companyCode}
AND    DIVISION_CODE = #{divisionCode}

SELECT COM_RVC_RATE        AS rvcRate
      ,COM_DE_MINIMIS_RATE AS deMinimisRate
FROM   FTA_MASTER
WHERE  FTA_CODE = #{ftaCode}
AND    COMPANY_CODE = #{companyCode}

SELECT NATION_CODE
FROM   FTA_APPLY_NATION
WHERE  FTA_CODE = #{ftaCode}

SELECT 
FROM   FCR_RESULT FRD
WHERE  FRD.SALES_NO = #{salesNo}
AND    FRD.SALES_SEQ = #{salesSeq}
AND    FRD.FTA_CODE = #{ftaCode}
AND    FRD.DIVISION_CODE = #{divisionCode}
AND    FRD.COMPANY_CODE = #{companyCode}
AND    FRD.COMPANY_COO_YN = 'Y'

SELECT 
FROM   FCR_RESULT FRD
WHERE  FRD.SALES_NO = #{salesNo}
AND    FRD.SALES_SEQ = #{salesSeq}
AND    FRD.FTA_CODE = #{ftaCode}
AND    FRD.DIVISION_CODE = #{divisionCode}
AND    FRD.COMPANY_CODE = #{companyCode}
AND    FRD.COMPANY_COO_YN = 'N'
AND    FRD.STATUS = 'N'

SELECT V.SALES_SEQ AS reqSalesSeq ,V.FTA_CODE AS reqFtaCode ,V.DIVISION_CODE AS reqDivisionCode ,R.* FROM (
SELECT #{r.salesSeq} AS SALES_SEQ, #{r.ftaCode} AS FTA_CODE, #{r.divisionCode} AS DIVISION_CODE
) V LEFT JOIN LATERAL (SELECT * FROM ( (SELECT ,'Y' AS matchTier FROM FCR_RESULT FRD WHERE FRD.SALES_NO = #{salesNo} AND FRD.SALES_SEQ = V.SALES_SEQ AND FRD.FTA_CODE = V.FTA_CODE AND FRD.DIVISION_CODE = V.DIVISION_CODE AND FRD.COMPANY_CODE = #{companyCode} AND FRD.COMPANY_COO_YN = 'Y' FETCH FIRST 1 ROW ONLY) UNION ALL (SELECT ,'N' AS matchTier FROM FCR_RESULT FRD WHERE FRD.SALES_NO = #{salesNo} AND FRD.SALES_SEQ = V.SALES_SEQ AND FRD.FTA_CODE = V.FTA_CODE AND FRD.DIVISION_CODE = V.DIVISION_CODE AND FRD.COMPANY_CODE = #{companyCode} AND FRD.COMPANY_COO_YN = 'N' AND FRD.STATUS = 'N' FETCH FIRST 1 ROW ONLY) ) TIERS ORDER BY matchTier DESC FETCH FIRST 1 ROW ONLY) R ON TRUE

mapper.update:
UPDATE FCR_MST FM SET RULE_CONTENTS = V.RULE_CONTENTS ,FTA_COO_YN = V.FTA_COO_YN ,COMPANY_COO_YN = V.COMPANY_COO_YN ,RCEP_COO_NATION = V.RCEP_COO_NATION FROM (
SELECT #{r.salesNo} AS SALES_NO, #{r.salesSeq} AS SALES_SEQ, #{r.ftaCode} AS FTA_CODE, #{r.divisionCode} AS DIVISION_CODE, #{r.companyCode} AS COMPANY_CODE, #{r.ruleContents} AS RULE_CONTENTS, #{r.ftaCooYn} AS FTA_COO_YN, #{r.companyCooYn} AS COMPANY_COO_YN, #{r.rcepCooNation} AS RCEP_COO_NATION
) V WHERE FM.SALES_NO = V.SALES_NO AND FM.SALES_SEQ = V.SALES_SEQ AND FM.FTA_CODE = V.FTA_CODE AND FM.DIVISION_CODE = V.DIVISION_CODE AND FM.COMPANY_CODE = V.COMPANY_CODE
